@Test
public void testManyItemSequence() {
    // Build test sequence
    try {
        // Add three items
        sb.reset(abvsResult);
        getTaggedValuePointable(1, tvp1);
        sb.addItem(tvp1);
        getTaggedValuePointable(2.0, tvp2);
        sb.addItem(tvp2);
        getTaggedValuePointable("three", tvp3);
        sb.addItem(tvp3);
        sb.finish();
    } catch (IOException e) {
        Assert.fail("Test failed to write the sequence pointable.");
    }
    tvp.set(abvsResult);
    // Check results.
    if (tvp.getTag() != ValueTag.SEQUENCE_TAG) {
        Assert.fail("Sequence tag is incorrect. Expected: " + ValueTag.SEQUENCE_TAG + " Got: " + tvp.getTag());
    }
    tvp.getValue(sp);
    if (sp.getEntryCount() != 3) {
        Assert.fail("Sequence size is incorrect. Expected: 3 Got: " + sp.getEntryCount());
    }
    sp.getEntry(0, tvp);
    if (tvp.getTag() != ValueTag.XS_INT_TAG) {
        Assert.fail("Sequence item one type tag is incorrect. Expected: " + ValueTag.XS_INT_TAG + " Got: " + tvp.getTag());
    }
    if (!FunctionHelper.arraysEqual(tvp, tvp1)) {
        Assert.fail("Sequence item one is incorrect. Expected: " + ValueTag.XS_INT_TAG + " Got: " + tvp.getTag());
    }
    sp.getEntry(1, tvp);
    if (tvp.getTag() != ValueTag.XS_DOUBLE_TAG) {
        Assert.fail("Sequence item two type tag is incorrect. Expected: " + ValueTag.XS_DOUBLE_TAG + " Got: " + tvp.getTag());
    }
    if (!FunctionHelper.arraysEqual(tvp, tvp2)) {
        Assert.fail("Sequence item two is incorrect. Expected: " + ValueTag.XS_DOUBLE_TAG + " Got: " + tvp.getTag());
    }
    sp.getEntry(2, tvp);
    if (tvp.getTag() != ValueTag.XS_STRING_TAG) {
        Assert.fail("Sequence item three type tag is incorrect. Expected: " + ValueTag.XS_STRING_TAG + " Got: " + tvp.getTag());
    }
    if (!FunctionHelper.arraysEqual(tvp, tvp3)) {
        Assert.fail("Sequence item three is incorrect. Expected: " + ValueTag.XS_STRING_TAG + " Got: " + tvp.getTag());
    }
}

